  "dashboard.indicator.backtest.executionAssumptions.bodyAggressive1m": "Agressivo (cripto): sinais da mesma barra na estratégia TF {sig}, preenchidos dentro de barras {exec} (≈10s de pesquisa ao vivo). SL/TP pode ser acionado mais cedo nas subbarras.",
