  "dashboard.indicator.backtest.executionAssumptions.bodyNextBar": "Depois que o sinal for confirmado no fechamento de uma barra, os preenchimentos usam a abertura da próxima barra (mais deslizamento). Os carimbos de data e hora de negociação geralmente mudam uma barra em relação aos marcadores no gráfico.",
  "dashboard.indicator.backtest.executionAssumptions.bodySameBar": "Depois que o sinal é confirmado no fechamento de uma barra, os preenchimentos usam o fechamento dessa barra (mais deslizamento). Os carimbos de data e hora se alinham com os marcadores do gráfico; os resultados são geralmente mais otimistas.",
  "dashboard.indicator.backtest.executionAssumptions.bodyScriptStandard": "Backtest da estratégia de script: handle_data é executado em cada barra fechada no período da estratégia; os pedidos do script são atendidos na próxima barra aberta por padrão (mais derrapagens/taxas). Este não é o indicador de alternância estrito/não estrito — é o caminho de reprodução de script padrão.",
  "dashboard.indicator.backtest.executionAssumptions.bodyStrict": "Modo estrito: sinaliza apenas em barras fechadas, preenchido na próxima barra aberta (mais deslizamento). As partidas vivem no modo estrito – conservador, mas mais realista.",
