  "fastAnalysis.indicatorsProSubtitle": "Alinhado com backend `MarketDataCollector._calculate_indicators` (estilo mainstream): RSI(14) é suavizado por Wilder. MACD(12,26,9) usa EMAs semeados em SMA em fechamentos; DIF da barra 26 em diante; DEA = EMA9 da série DIF (~34+ barras para uma linha de sinal completa). MAs são SMAs. O pivô usa a barra anterior H/L/C. Swing = extremos altos/baixos de 20 barras. Bollinger = SMA(20) ± 2×população σ; os níveis agregados usam BB_upper/BB_lower. ATR(14) é Wilder, acorrentado à última barra. Consulte docs/INDICATOR_DEFINITIONS_CN.md para relação de volume e posição de intervalo.",
  "fastAnalysis.indicatorsProTableTitle": "Parâmetros quant (estilo institucional)",
