  "user.login.hero.welcome": "Bem-vindo à QuantDinger",
  "user.login.hero.welcomeDesc": "Faça login para continuar seu fluxo de trabalho de pesquisa e negociação.",
  "user.login.infos": "QuantDinger é uma ferramenta de análise de ações multiagente de IA que não possui qualificações de consultoria de investimento em valores mobiliários. Todos os resultados de análises, pontuações e opiniões de referência na plataforma são gerados automaticamente pela IA com base em dados históricos e são apenas para aprendizagem, pesquisa e intercâmbio técnico, e não constituem qualquer conselho de investimento ou base de tomada de decisão. O investimento em ações envolve risco de mercado, risco de liquidez, risco de política e outros riscos, que podem levar a perdas de capital. Os usuários devem tomar decisões independentes com base na sua capacidade de tolerância ao risco, e arcar com as consequências de qualquer comportamento de investimento e seus resultados utilizando esta ferramenta. Risco de mercado, o investimento precisa ser cauteloso.",
  "user.login.legal.agree": "Li e concordo com o Aviso Legal",
  "user.login.legal.agreePrefix": "Eu concordo com o",
  "user.login.legal.and": "e",
  "user.login.legal.collapse": "Ocultar isenção de responsabilidade legal",
  "user.login.legal.content": "QuantDinger é uma ferramenta de análise de estoque multiagente de IA e não fornece consultoria de investimento. Todos os resultados de análises, pontuações e referências são gerados por IA com base em dados históricos e servem apenas para aprendizado, pesquisa e intercâmbio técnico. Não constituem aconselhamento de investimento nem base para a tomada de decisões. Os investimentos em ações envolvem riscos de mercado, de liquidez e de política, que podem levar à perda do principal. Os usuários devem tomar decisões independentes com base na sua tolerância ao risco e arcar com as consequências de qualquer comportamento e resultados de investimento utilizando esta ferramenta.",
  "user.login.legal.required": "Por favor, leia e verifique o Aviso Legal primeiro",
