  "user.login.privacy.collapse": "Ocultar Política de Privacidade",
  "user.login.privacy.content": "Valorizamos a sua privacidade e proteção de dados. (1) Escopo da coleta: Coletamos apenas as informações necessárias para fornecer o serviço (por exemplo, e-mail, número de celular, código do país, endereço da carteira Web3) e registros/dados do dispositivo limitados. (2) Finalidade de uso: login da conta e verificação de segurança, provisionamento de recursos, solução de problemas e requisitos de conformidade. (3) Armazenamento e segurança: Os dados são criptografados e com acesso controlado para evitar acesso não autorizado, divulgação ou perda. (4) Compartilhamento e terceiros: Não compartilhamos dados pessoais com terceiros, exceto conforme exigido por lei ou para fornecer o serviço; quando estão envolvidos serviços de terceiros (por exemplo, carteiras, fornecedores de SMS), o processamento é limitado ao âmbito mínimo exigido. (5) Cookies/armazenamento local: Usado para sessão e estado de login (por exemplo, tokens, PHPSESSID). Você pode limpá-los ou restringi-los em seu navegador. (6) Seus direitos: Você pode exercer direitos de acesso, correção, exclusão e retirada de consentimento conforme permitido por lei. (7) Alterações e avisos: Forneceremos avisos importantes para atualizações. O uso continuado indica que você leu e concordou com os termos atualizados. Se você não concordar, pare de usar o serviço e entre em contato conosco.",
  "user.login.privacy.title": "Política de Privacidade",
  "user.login.privacy.view": "Ver Política de Privacidade",
